-- The fixture schema (../migrations/db/0001_schema.sql) in Postgres's own types, each column the
-- type of the attribute the tests read it as. Integer keys are identities, which the harness
-- moves past rows a test seeds with their own keys.
CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  role TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  suspended BIGINT NOT NULL DEFAULT 0,
  age BIGINT,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ
);

CREATE TABLE posts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users (id),
  title TEXT NOT NULL,
  published BIGINT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ
);

CREATE TABLE samples (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  label TEXT,
  quantity BIGINT,
  ratio DOUBLE PRECISION,
  enabled BIGINT,
  stamp TEXT,
  settings TEXT
);

CREATE TABLE accounts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  is_active BOOLEAN,
  external_account_id TEXT,
  html_url TEXT,
  user_id BIGINT,
  sha256_hash TEXT,
  person_identifier TEXT
);

CREATE TABLE api_keys (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  scopes TEXT,
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ
);

CREATE TABLE products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  price_cents BIGINT NOT NULL CHECK (price_cents >= 0)
);

CREATE TABLE profiles (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users (id),
  bio TEXT
);

CREATE TABLE comments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id BIGINT REFERENCES posts (id),
  body TEXT
);

CREATE TABLE json_values (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  checked JSONB,
  value JSONB
);
